1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13		"syscall"
14	)
15	
16	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
17	const (
18		stateFileName = "retention-state.json"
19		lockFileName  = ".retention.lock"
20	)
21	
22	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
23	//
24	// 同一个目录可以被本机上的多个程序（进程）同时打开：
25	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
26	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
27	type Store struct {
28		dir string
29	
30		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
31		opMu sync.RWMutex
32	}
33	
34	// Open 打开（或创建）一个本地保存位置。
35	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
36	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
37	// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
38	// 缺少解除原因或解除日期、解除日期早于冻结日期、已销毁档案与已关闭清册
39	// 对应不上、已关闭清册条目保存的类别、起算日或截止日（须为销毁时最终
40	// 生效的期限）与档案登记内容不一致、修订记录衔接不上、成功修订编号在保存
41	// 历史中不唯一或与已关闭清册的申请编号相同）时返回 ErrCorruptState，
42	// 不会返回可继续办理的保管库，已有记录保持原样，不会被清空、修补或覆盖。
43	func Open(dir string) (*Store, error) {
44		if dir == "" {
45			return nil, errors.New("retention: 保存位置不能为空")
46		}
47		if err := os.MkdirAll(dir, 0o755); err != nil {
48			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
49		}
50		s := &Store{dir: dir}
51		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
52		if _, err := s.load(); err != nil {
53			return nil, err
54		}
55		return s, nil
56	}
57	
58	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
59	func (s *Store) Close() error { return nil }
60	
61	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
62	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
63	
64	// lock 取得跨进程排他锁，返回解锁函数。
65	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
66	func (s *Store) lock() (func(), error) {
67		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
68		if err != nil {
69			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
70		}
71		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
72			f.Close()
73			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
74		}
75		return func() {
76			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
77			_ = f.Close()
78		}, nil
79	}
80	
81	// rlock 取得跨进程共享锁，用于只读核对。
82	func (s *Store) rlock() (func(), error) {
83		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
84		if err != nil {
85			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
86		}
87		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
88			f.Close()
89			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
90		}
91		return func() {
92			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
93			_ = f.Close()
94		}, nil
95	}
96	
97	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
98	//
99	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
100	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
101	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
102	// 绝不只使用前一段内容，也不会改动原文件。
103	//
104	// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
105	// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
106	// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
107	// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
108	//
109	// 已销毁档案与已关闭清册也必须相互对应：每份已销毁档案记下的申请编号
110	// 必须能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案
111	// 也必须存在、标成已销毁并指回这份清册。已销毁档案找不到清册、同一档案
112	// 出现在多份清册、归属指向别的申请，或未销毁档案仍挂有清册申请编号，
113	// 都说明记录已无法说明档案由哪次申请销毁，整份保管库判为损坏并返回
114	// ErrCorruptState，错误信息指明涉及的档案编号与相关申请编号。
115	//
116	// 仅归属对应还不够：已关闭清册中的每条档案条目是销毁成功那一刻登记内容
117	// 的快照，其类别、起算日、截止日必须与对应档案当前保存的登记内容逐项
118	// 一致。档案销毁后期限不能再修订，编号、类别与起算日也从不改动，所以
119	// 合法记录中两处必然相同；截止日必须是销毁时最终生效的期限（最后一次
120	// 成功修订的新截止日，没有修订时为最初登记的截止日），即使修订历史衔接
121	// 完整、清册归属正确，保存成最初登记的截止日也属损坏。任一条目在类别、
122	// 起算日、截止日任一项上不一致，两处记录就互相矛盾，整份保管库判为
123	// 损坏并返回 ErrCorruptState，错误信息指明清册申请编号、档案编号与
124	// 不一致的项目；绝不挑选其中一处作为可信记录，也不通过覆盖清册、修改
125	// 档案或删除记录消除差异。一份清册收录多份档案时，一份条目矛盾就使
126	// 整份保管库无法读取，不会返回其余条目的正常结果。
127	//
128	// 最初截止日、修订记录与当前截止日也必须连续对应：第一条修订的原截止日
129	// 等于最初截止日，后续每条的原截止日等于上一条的新截止日，最后一条的
130	// 新截止日等于当前截止日；没有修订时最初截止日与当前截止日相同。修订
131	// 日期仅用于记录，历史不按该日期重新排列。出现断开的修订关系、当前截止日
132	// 与末次修订不符、修订列表中存在空记录，或已有修订却缺少最初截止日时，
133	// 两个日期中任何一个都不能当作可靠依据，整份保管库判为损坏并返回
134	// ErrCorruptState，错误信息指明涉及的档案编号，能对应到具体修订时
135	// 同时指明修订编号。
136	//
137	// 每个成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
138	// 已关闭清册的申请编号相同——与办理时“修订编号全库唯一、与销毁申请编号
139	// 互不占用”的要求一致。同一档案历史中重复出现同一编号、不同档案各自保存
140	// 同号修订（即使两条记录内容完全相同），或某条修订的编号与一份已关闭
141	// 清册的申请编号相同，都无法仅凭编号唯一确定应取回哪条修订，整份保管库
142	// 判为损坏并返回 ErrCorruptState；绝不合并记录或挑选其中一条继续使用。
143	// 错误信息指明冲突编号：同档案重复时指出该档案，跨档案重复时指出两份
144	// 档案，与清册冲突时指出修订所属档案与清册申请编号。
145	func (s *Store) load() (*storeData, error) {
146		raw, err := os.ReadFile(s.statePath())
147		if err != nil {
148			if errors.Is(err, os.ErrNotExist) {
149				return newStoreData(), nil
150			}
151			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
152		}
153		trimmed := bytes.TrimSpace(raw)
154		if len(trimmed) == 0 {
155			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
156		}
157		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
158		if string(trimmed) == "null" {
159			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
160		}
161		data := newStoreData()
162		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
163		// 合法对象后面再拼接任何内容都会在这里报错。
164		if err := json.Unmarshal(raw, data); err != nil {
165			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
166		}
167		if data.Archives == nil {
168			data.Archives = map[string]*archiveRecord{}
169		}
170		if data.Manifests == nil {
171			data.Manifests = map[string]*manifestRecord{}
172		}
173		// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
174		// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
175		// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
176		// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
177		if err := validateFreezeReleaseRecords(data); err != nil {
178			return nil, err
179		}
180		// 已销毁档案与已关闭清册必须相互对应，否则无法说明档案由哪次申请销毁。
181		// 关系损坏时绝不挑选其中一份记录继续使用，也不补清册或改销毁标记。
182		if err := validateManifestConsistency(data); err != nil {
183			return nil, err
184		}
185		// 兼容引入修订功能之前保存的保管库：没有修订记录也没有最初截止日时，
186		// 登记截止日就是最初截止日。已有修订却缺少最初截止日的记录不能据此
187		// 冒充，由 validateRevisionContinuity 按损坏拒绝。
188		for _, ar := range data.Archives {
189			if ar != nil && len(ar.Revisions) == 0 && ar.InitialEnd.IsZero() {
190				ar.InitialEnd = ar.End
191			}
192		}
193		// 已关闭清册中的每条档案条目是销毁成功那一刻的登记内容快照，
194		// 其类别、起算日与截止日必须与对应档案保存的登记内容逐项一致，
195		// 截止日必须是该档案销毁时最终生效的期限，不能拿最初登记的截止日顶替。
196		if err := validateManifestSnapshots(data); err != nil {
197			return nil, err
198		}
199		// 最初截止日、修订记录与当前截止日必须连续衔接，否则当前期限与
200		// 历史期限相互矛盾，任何一个日期都不能当作核对依据。
201		if err := validateRevisionContinuity(data); err != nil {
202			return nil, err
203		}
204		// 成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
205		// 已关闭清册的申请编号相同——与办理时全库唯一、编号互不占用的要求一致。
206		if err := validateRevisionIDs(data); err != nil {
207			return nil, err
208		}
209		return data, nil
210	}
211	
212	// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
213	//
214	// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
215	// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
216	// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
217	// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
218	// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
219	// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
220	// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
221	func validateFreezeReleaseRecords(data *storeData) error {
222		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
223		archiveIDs := make([]string, 0, len(data.Archives))
224		for id := range data.Archives {
225			archiveIDs = append(archiveIDs, id)
226		}
227		sort.Strings(archiveIDs)
228		for _, id := range archiveIDs {
229			ar := data.Archives[id]
230			if ar == nil {
231				return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
232					id, ErrCorruptState)
233			}
234			for _, fr := range ar.Freezes {
235				if fr == nil {
236					return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
237						id, ErrCorruptState)
238				}
239				if !fr.Released {
240					// 未解除冻结没有解除日期与原因是合法状态。
241					continue
242				}
243				switch {
244				case strings.TrimSpace(fr.ReleaseReason) == "":
245					return fmt.Errorf(
246						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
247						id, fr.ID, ErrCorruptState)
248				case fr.ReleasedOn == nil:
249					return fmt.Errorf(
250						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
251						id, fr.ID, ErrCorruptState)
252				case fr.ReleasedOn.IsZero():
253					return fmt.Errorf(
254						"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
255						id, fr.ID, ErrCorruptState)
256				case fr.ReleasedOn.Before(fr.FrozenOn):
257					return fmt.Errorf(
258						"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
259						id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
260				}
261			}
262		}
263		return nil
264	}
265	
266	// validateManifestConsistency 检查已销毁档案与已关闭清册之间的对应关系。
267	//
268	// 正常销毁保存的记录必然满足双向对应：每份已销毁档案记下的申请编号
269	// 能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案都
270	// 存在、标成已销毁，并指回这份清册。已销毁档案没有清册归属、归属的
271	// 清册不存在或未收录该档案、同一档案出现在多份清册、清册重复收录同一
272	// 档案、清册收录了不存在或未销毁的档案、档案归属指向别的申请，以及
273	// 未销毁档案仍挂有清册申请编号，都说明保存内容已损坏，返回可由
274	// ErrCorruptState 识别的错误，并在信息中给出涉及的档案编号与相关
275	// 申请编号，便于定位记录。校验覆盖整个保管库，与本次办理名单无关；
276	// 未销毁且没有清册归属的档案是合法记录，不在此报错。
277	func validateManifestConsistency(data *storeData) error {
278		// map 遍历顺序不稳定，按编号排序后再检查，保证错误信息稳定。
279		archiveIDs := make([]string, 0, len(data.Archives))
280		for id := range data.Archives {
281			archiveIDs = append(archiveIDs, id)
282		}
283		sort.Strings(archiveIDs)
284		for _, id := range archiveIDs {
285			ar := data.Archives[id]
286			if ar == nil {
287				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
288				continue
289			}
290			if !ar.Destroyed {
291				if ar.ManifestID != "" {
292					return fmt.Errorf(
293						"retention: 档案 %s 未销毁却挂有清册申请编号 %s，记录已损坏: %w",
294						id, ar.ManifestID, ErrCorruptState)
295				}
296				continue
297			}
298			if ar.ManifestID == "" {
299				return fmt.Errorf(
300					"retention: 档案 %s 已销毁但没有记录所属清册的申请编号，记录已损坏: %w",
301					id, ErrCorruptState)
302			}
303			rec, ok := data.Manifests[ar.ManifestID]
304			if !ok || rec == nil {
305				return fmt.Errorf(
306					"retention: 档案 %s 已销毁，但其所属清册 %s 不存在，记录已损坏: %w",
307					id, ar.ManifestID, ErrCorruptState)
308			}
309			count := 0
310			for _, e := range rec.Entries {
311				if e.ID == id {
312					count++
313				}
314			}
315			if count != 1 {
316				return fmt.Errorf(
317					"retention: 档案 %s 在其所属清册 %s 中收录 %d 次（应恰好一次），记录已损坏: %w",
318					id, ar.ManifestID, count, ErrCorruptState)
319			}
320		}
321	
322		applicationIDs := make([]string, 0, len(data.Manifests))
323		for id := range data.Manifests {
324			applicationIDs = append(applicationIDs, id)
325		}
326		sort.Strings(applicationIDs)
327		for _, appID := range applicationIDs {
328			rec := data.Manifests[appID]
329			if rec == nil {
330				return fmt.Errorf(
331					"retention: 清册 %s 的内容缺失，记录已损坏: %w",
332					appID, ErrCorruptState)
333			}
334			seen := make(map[string]int, len(rec.Entries))
335			for _, e := range rec.Entries {
336				seen[e.ID]++
337				ar, ok := data.Archives[e.ID]
338				if !ok || ar == nil {
339					return fmt.Errorf(
340						"retention: 清册 %s 收录的档案 %s 不存在，记录已损坏: %w",
341						appID, e.ID, ErrCorruptState)
342				}
343				if !ar.Destroyed {
344					return fmt.Errorf(
345						"retention: 清册 %s 收录的档案 %s 未标记为已销毁，记录已损坏: %w",
346						appID, e.ID, ErrCorruptState)
347				}
348				if ar.ManifestID != appID {
349					return fmt.Errorf(
350						"retention: 清册 %s 收录的档案 %s 归属另一申请 %s，记录已损坏: %w",
351						appID, e.ID, ar.ManifestID, ErrCorruptState)
352				}
353			}
354			// 同一档案被同一份清册重复收录（档案侧的恰好一次检查只覆盖
355			// 归属指向该清册的情况，这里对全部收录记录再核对一遍）。
356			entryIDs := make([]string, 0, len(seen))
357			for id := range seen {
358				entryIDs = append(entryIDs, id)
359			}
360			sort.Strings(entryIDs)
361			for _, id := range entryIDs {
362				if seen[id] > 1 {
363					return fmt.Errorf(
364						"retention: 清册 %s 重复收录档案 %s（共 %d 次），记录已损坏: %w",
365						appID, id, seen[id], ErrCorruptState)
366				}
367			}
368		}
369		return nil
370	}
371	
372	// validateManifestSnapshots 检查每份已关闭清册中的档案条目是否与对应档案
373	// 当前保存的登记内容逐项一致。
374	//
375	// 清册在销毁成功那一刻关闭，条目是关闭瞬间登记内容的快照：档案销毁后
376	// 不能再修订期限，编号、类别与起算日也从不改动，因此合法记录中清册条目
377	// 的类别、起算日与截止日必然与对应档案保存的值相同——其中截止日必须是
378	// 该档案销毁时最终生效的期限（等于最后一次成功修订的新截止日；没有修订
379	// 时等于最初登记的截止日），不能拿最初登记的截止日顶替。延长、缩短或
380	// 改回曾经使用过的日期都沿用这一规则，不按修订记录中的办理日期重新选择。
381	//
382	// 任一条目在类别、起算日、截止日任一项上与档案不一致，两处记录就互相
383	// 矛盾，任何一处都不能当作可信依据：返回可由 ErrCorruptState 识别的错误，
384	// 绝不挑选其中一份继续使用，也不通过覆盖清册、修改档案或删除记录消除差异。
385	// 错误信息给出清册申请编号、档案编号与不一致的项目（类别、起算日、
386	// 保管截止日，并附上两处各自保存的值）。校验覆盖整个保管库的全部清册
387	// 与全部条目，与本次办理名单或查询目标无关：一份清册收录多份档案时，
388	// 只要有一份条目矛盾，整份保管库都判为损坏，不会返回其余条目的正常结果。
389	func validateManifestSnapshots(data *storeData) error {
390		// map 遍历顺序不稳定，按申请编号、条目顺序检查，保证错误信息稳定。
391		appIDs := make([]string, 0, len(data.Manifests))
392		for appID := range data.Manifests {
393			appIDs = append(appIDs, appID)
394		}
395		sort.Strings(appIDs)
396		for _, appID := range appIDs {
397			rec := data.Manifests[appID]
398			if rec == nil {
399				// 缺失的清册记录已由 validateManifestConsistency 报告。
400				continue
401			}
402			for _, e := range rec.Entries {
403				ar, ok := data.Archives[e.ID]
404				if !ok || ar == nil {
405					// 清册收录不存在档案等归属问题已由 validateManifestConsistency 报告。
406					continue
407				}
408				items := make([]string, 0, 3)
409				if e.Category != ar.Category {
410					items = append(items, fmt.Sprintf("类别（清册 %q，档案 %q）", e.Category, ar.Category))
411				}
412				if !e.Start.Equal(ar.Start) {
413					items = append(items, fmt.Sprintf("起算日（清册 %s，档案 %s）", e.Start, ar.Start))
414				}
415				if !e.End.Equal(ar.End) {
416					items = append(items, fmt.Sprintf("保管截止日（清册 %s，档案 %s）", e.End, ar.End))
417				}
418				if len(items) > 0 {
419					return fmt.Errorf(
420						"retention: 清册 %s 中档案 %s 的条目与档案登记内容不一致：%s，记录已损坏: %w",
421						appID, e.ID, strings.Join(items, "、"), ErrCorruptState)
422				}
423			}
424		}
425		return nil
426	}
427	
428	// validateRevisionContinuity 检查每份档案的最初截止日、修订记录与当前截止日
429	// 是否连续对应。
430	//
431	// 正常办理保存的记录必然满足：第一条修订的原截止日等于最初截止日，后续每条
432	// 的原截止日等于上一条的新截止日，最后一条的新截止日等于当前截止日；没有
433	// 修订时最初截止日与当前截止日相同。修订日期仅用于记录办理时间，不决定生效
434	// 先后，因此历史不按修订日期重新排列，只按保存顺序核对衔接；期限被延长、
435	// 缩短或改回早先用过的日期，只要衔接完整都是合法记录。
436	//
437	// 出现断开的修订关系、当前截止日与末次修订的新截止日不符、修订列表中存在
438	// 空记录，或已有修订却缺少最初截止日（不能把当前期限冒充最初期限）时，
439	// 保存内容已无法说明期限如何演变，返回可由 ErrCorruptState 识别的错误，
440	// 并在信息中给出涉及的档案编号；能对应到具体修订时同时给出修订编号。
441	// 校验覆盖整个保管库的全部档案（含已销毁的），与本次办理名单无关。
442	func validateRevisionContinuity(data *storeData) error {
443		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
444		archiveIDs := make([]string, 0, len(data.Archives))
445		for id := range data.Archives {
446			archiveIDs = append(archiveIDs, id)
447		}
448		sort.Strings(archiveIDs)
449		for _, id := range archiveIDs {
450			ar := data.Archives[id]
451			if ar == nil {
452				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
453				continue
454			}
455			if len(ar.Revisions) == 0 {
456				// 没有修订时最初截止日与当前截止日必须相同
457				// （旧记录缺少最初截止日的情形已在 load 中按登记截止日补齐）。
458				if !ar.InitialEnd.Equal(ar.End) {
459					return fmt.Errorf(
460						"retention: 档案 %s 没有修订记录，但最初截止日 %s 与当前截止日 %s 不一致，记录已损坏: %w",
461						id, ar.InitialEnd, ar.End, ErrCorruptState)
462				}
463				continue
464			}
465			for i, rec := range ar.Revisions {
466				if rec == nil {
467					return fmt.Errorf(
468						"retention: 档案 %s 的修订列表第 %d 条为空记录，记录已损坏: %w",
469						id, i+1, ErrCorruptState)
470				}
471			}
472			if ar.InitialEnd.IsZero() {
473				return fmt.Errorf(
474					"retention: 档案 %s 已有修订记录（首条为 %s）却缺少最初截止日，记录已损坏: %w",
475					id, ar.Revisions[0].ID, ErrCorruptState)
476			}
477			// 按保存顺序逐条核对衔接：每条的原截止日必须等于此前生效的截止日。
478			expected := ar.InitialEnd
479			for _, rec := range ar.Revisions {
480				if !rec.OldEnd.Equal(expected) {
481					return fmt.Errorf(
482						"retention: 档案 %s 的修订 %s 的原截止日 %s 与此前生效的截止日 %s 不衔接，记录已损坏: %w",
483						id, rec.ID, rec.OldEnd, expected, ErrCorruptState)
484				}
485				expected = rec.NewEnd
486			}
487			if !ar.End.Equal(expected) {
488				return fmt.Errorf(
489					"retention: 档案 %s 的当前截止日 %s 与末次修订 %s 的新截止日 %s 不符，记录已损坏: %w",
490					id, ar.End, ar.Revisions[len(ar.Revisions)-1].ID, expected, ErrCorruptState)
491			}
492		}
493		return nil
494	}
495	
496	// validateRevisionIDs 检查成功修订编号在整个保管库内的唯一性，以及与已关闭
497	// 清册申请编号的互不占用。
498	//
499	// 正常办理保存的记录必然满足：每个修订编号在全部档案的修订历史中只出现
500	// 一次，且没有任何编号同时被用作成功销毁申请的编号。同一档案历史中重复
501	// 使用同一编号、不同档案各自保存同号修订（即使两条记录的日期、原因等
502	// 内容完全相同），或修订编号与一份已关闭清册的申请编号相同，都会使
503	// “按编号重试取回唯一一条修订”无法成立，返回可由 ErrCorruptState 识别
504	// 的错误：绝不合并重复记录，也不挑选其中一条继续使用。
505	//
506	// 错误信息给出冲突的修订编号与涉及的档案编号；跨档案重复时同时给出两份
507	// 档案，与清册冲突时给出清册的申请编号。校验覆盖整个保管库的全部档案
508	// （含已销毁的），与本次办理名单或查询目标无关。修订编号为空白同样不能
509	// 作为成功记录存在，一并按损坏处理。
510	func validateRevisionIDs(data *storeData) error {
511		owners := make(map[string]string)
512		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
513		archiveIDs := make([]string, 0, len(data.Archives))
514		for id := range data.Archives {
515			archiveIDs = append(archiveIDs, id)
516		}
517		sort.Strings(archiveIDs)
518		for _, id := range archiveIDs {
519			ar := data.Archives[id]
520			if ar == nil {
521				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
522				continue
523			}
524			for _, rec := range ar.Revisions {
525				if rec == nil {
526					// 空记录已由 validateRevisionContinuity 报告。
527					continue
528				}
529				if strings.TrimSpace(rec.ID) == "" {
530					return fmt.Errorf(
531						"retention: 档案 %s 的修订历史中存在没有编号的修订记录，记录已损坏: %w",
532						id, ErrCorruptState)
533				}
534				if owner, ok := owners[rec.ID]; ok {
535					if owner == id {
536						return fmt.Errorf(
537							"retention: 修订编号 %s 在档案 %s 的历史中出现多条记录，保存记录已损坏: %w",
538							rec.ID, id, ErrCorruptState)
539					}
540					return fmt.Errorf(
541						"retention: 修订编号 %s 同时保存在档案 %s 与档案 %s 的修订历史中，保存记录已损坏: %w",
542						rec.ID, owner, id, ErrCorruptState)
543				}
544				owners[rec.ID] = id
545			}
546		}
547		// 修订编号与销毁申请编号互不占用：任何已关闭清册的申请编号都不能
548		// 同时是一条已保存修订的编号。申请编号按排序遍历，错误信息稳定。
549		appIDs := make([]string, 0, len(data.Manifests))
550		for appID := range data.Manifests {
551			appIDs = append(appIDs, appID)
552		}
553		sort.Strings(appIDs)
554		for _, appID := range appIDs {
555			if owner, ok := owners[appID]; ok {
556				return fmt.Errorf(
557					"retention: 档案 %s 的修订编号 %s 与已关闭清册的申请编号 %s 相同，保存记录已损坏: %w",
558					owner, appID, appID, ErrCorruptState)
559			}
560		}
561		return nil
562	}
563	
564	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
565	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
566	func (s *Store) save(data *storeData) error {
567		buf, err := json.MarshalIndent(data, "", "  ")
568		if err != nil {
569			return fmt.Errorf("retention: 状态编码失败: %w", err)
570		}
571		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
572		if err != nil {
573			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
574		}
575		tmpName := tmp.Name()
576		cleanup := func() { _ = os.Remove(tmpName) }
577		if _, err := tmp.Write(buf); err != nil {
578			tmp.Close()
579			cleanup()
580			return fmt.Errorf("retention: 写入状态失败: %w", err)
581		}
582		if err := tmp.Sync(); err != nil {
583			tmp.Close()
584			cleanup()
585			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
586		}
587		if err := tmp.Close(); err != nil {
588			cleanup()
589			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
590		}
591		if err := os.Rename(tmpName, s.statePath()); err != nil {
592			cleanup()
593			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
594		}
595		// 刷目录，确保 rename 在崩溃后仍然落盘。
596		if dir, err := os.Open(s.dir); err == nil {
597			_ = dir.Sync()
598			_ = dir.Close()
599		}
600		return nil
601	}
602	
603	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
604	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
605	func (s *Store) mutate(fn func(*storeData) error) error {
606		s.opMu.Lock()
607		defer s.opMu.Unlock()
608		unlock, err := s.lock()
609		if err != nil {
610			return err
611		}
612		defer unlock()
613		data, err := s.load()
614		if err != nil {
615			return err
616		}
617		if err := fn(data); err != nil {
618			return err
619		}
620		return s.save(data)
621	}
622	
623	// view 在共享锁内重读状态并执行只读查询。
624	func (s *Store) view(fn func(*storeData) error) error {
625		s.opMu.RLock()
626		defer s.opMu.RUnlock()
627		unlock, err := s.rlock()
628		if err != nil {
629			return err
630		}
631		defer unlock()
632		data, err := s.load()
633		if err != nil {
634			return err
635		}
636		return fn(data)
637	}
638

