package retention

import (
	"strconv"
	"strings"
)

// Date 是按日历日期（年月日）比较的日期，与时区和夏令时无关。
//
// 对外的文本格式统一为 YYYY-MM-DD。零值表示无效日期，不能用于业务。
type Date struct {
	year  int
	month int
	day   int
}

// ParseDate 按 YYYY-MM-DD 解析日期。
// 只接受完整的四位年份、两位月份、两位日期，且日期必须真实存在。
func ParseDate(s string) (Date, error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return Date{}, &InvalidDateError{Value: s}
	}
	year, err := strconv.Atoi(s[0:4])
	if err != nil {
		return Date{}, &InvalidDateError{Value: s}
	}
	month, err := strconv.Atoi(s[5:7])
	if err != nil {
		return Date{}, &InvalidDateError{Value: s}
	}
	day, err := strconv.Atoi(s[8:10])
	if err != nil {
		return Date{}, &InvalidDateError{Value: s}
	}
	if !validCalendarDate(year, month, day) {
		return Date{}, &InvalidDateError{Value: s}
	}
	return Date{year, month, day}, nil
}

// MustParseDate 按 YYYY-MM-DD 解析日期，失败即 panic。
// 只适合在测试或字面量构造中使用。
func MustParseDate(s string) Date {
	d, err := ParseDate(s)
	if err != nil {
		panic(err)
	}
	return d
}

// String 返回 YYYY-MM-DD 形式的文本。
func (d Date) String() string {
	var b strings.Builder
	b.Grow(10)
	writePadded(&b, d.year, 4)
	b.WriteByte('-')
	writePadded(&b, d.month, 2)
	b.WriteByte('-')
	writePadded(&b, d.day, 2)
	return b.String()
}

// IsZero 报告日期是否为零值（未设置）。
func (d Date) IsZero() bool { return d.year == 0 && d.month == 0 && d.day == 0 }

// Before 按日历日期报告 d 是否早于 other。
func (d Date) Before(other Date) bool {
	if d.year != other.year {
		return d.year < other.year
	}
	if d.month != other.month {
		return d.month < other.month
	}
	return d.day < other.day
}

// After 按日历报告 d 是否晚于 other。
func (d Date) After(other Date) bool { return other.Before(d) }

// Equal 按日历报告两个日期是否相同。
func (d Date) Equal(other Date) bool {
	return d.year == other.year && d.month == other.month && d.day == other.day
}

// MarshalJSON 按 YYYY-MM-DD 序列化。
func (d Date) MarshalJSON() ([]byte, error) {
	return []byte(`"` + d.String() + `"`), nil
}

// UnmarshalJSON 按 YYYY-MM-DD 形式反序列化并校验真实日期。
func (d *Date) UnmarshalJSON(data []byte) error {
	if len(data) < 2 || data[0] != '"' || data[len(data)-1] != '"' {
		return &InvalidDateError{Value: string(data)}
	}
	parsed, err := ParseDate(string(data[1 : len(data)-1]))
	if err != nil {
		return err
	}
	*d = parsed
	return nil
}

func writePadded(b *strings.Builder, value, width int) {
	s := strconv.Itoa(value)
	for i := len(s); i < width; i++ {
		b.WriteByte('0')
	}
	b.WriteString(s)
}

func validCalendarDate(year, month, day int) bool {
	// 年份允许 0001..9999；月份、日期必须真实存在，含闰年规则。
	if year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 {
		return false
	}
	daysInMonth := 31
	switch month {
	case 4, 6, 9, 11:
		daysInMonth = 30
	case 2:
		leap := year%4 == 0 && (year%100 != 0 || year%400 == 0)
		if leap {
			daysInMonth = 29
		} else {
			daysInMonth = 28
		}
	}
	return day <= daysInMonth
}

// Package retention 提供在本机运行的档案保管期限与销毁清册功能。
//
// 调用 Open 选择一个本地保存位置后，可以：
//   - Register 登记档案条目（只登记元数据，不读取或保存真实文件）；
//   - Freeze / Release 记录同一档案的多条冻结及解除，解除不删除记录；
//   - Revise 修订尚未销毁档案的保管截止日，全库唯一的修订编号支持幂等重试；
//   - Check 在销毁前只做核对，一次看清整批所有阻碍，不销毁、不写清册、不占用申请编号；
//   - Destroy 一次选择多个档案办理销毁，全部满足条件才生成已关闭清册；
//   - History 按档案编号核对登记内容、全部冻结解除历史、当前状态与对应清册；
//   - GetManifest 按申请编号取回已关闭清册。
//
// 所有日期统一为 YYYY-MM-DD（见 ParseDate 与 Date），按日历日期比较，
// 不受时区或夏令时影响。
//
// 状态保存在所选目录下的 JSON 文件中，采用临时文件加原子替换写入；
// 同一位置被本机上的多个程序同时打开时，通过文件锁串行化每次办理，
// 先成功者生效，关闭后重新打开记录仍完整可查。
package retention

// Ready 表示包可以运行。
func Ready() bool { return true }

