1	package retention
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 已保存的销毁状态与已关闭清册必须相互对应：对应关系损坏时，
10	// 即使 JSON 能解析，Open 也必须按记录损坏失败（ErrCorruptState），
11	// 错误信息指出涉及的档案编号与相关申请编号，原文件保持原样。
12	func TestOpenRejectsBrokenManifestLink(t *testing.T) {
13		archive := func(extra string) string {
14			return `{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","freezes":[]` + extra + `}`
15		}
16		manifest := func(appID, entries string) string {
17			return `"` + appID + `":{"application_id":"` + appID + `","processed_on":"2025-01-10","entries":[` + entries + `]}`
18		}
19		entryA1 := `{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10"}`
20	
21		corrupt := map[string]struct {
22			state   string
23			wantIDs []string
24		}{
25			"已销毁但没有任何清册": {
26				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":true,"manifest_id":"APP-1"`) + `},"manifests":{}}`,
27				[]string{"A-1", "APP-1"},
28			},
29			"已销毁但归属的清册不存在": {
30				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":true,"manifest_id":"APP-9"`) + `},"manifests":{` + manifest("APP-1", entryA1) + `}}`,
31				[]string{"A-1", "APP-9"},
32			},
33			"已销毁但没有申请编号": {
34				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":true`) + `},"manifests":{` + manifest("APP-1", entryA1) + `}}`,
35				[]string{"A-1"},
36			},
37			"清册未收录该档案": {
38				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":true,"manifest_id":"APP-1"`) + `},"manifests":{` + manifest("APP-1", "") + `}}`,
39				[]string{"A-1", "APP-1"},
40			},
41			"清册重复收录同一档案": {
42				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":true,"manifest_id":"APP-1"`) + `},"manifests":{` + manifest("APP-1", entryA1+`,`+entryA1) + `}}`,
43				[]string{"A-1", "APP-1"},
44			},
45			"清册收录不存在的档案": {
46				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":true,"manifest_id":"APP-1"`) + `},"manifests":{` + manifest("APP-1", entryA1+`,`+`{"id":"A-2","category":"凭证","start":"2020-01-01","end":"2025-01-10"}`) + `}}`,
47				[]string{"A-2", "APP-1"},
48			},
49			"清册收录的档案未销毁": {
50				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":false`) + `},"manifests":{` + manifest("APP-1", entryA1) + `}}`,
51				[]string{"A-1", "APP-1"},
52			},
53			"未销毁档案挂有清册申请编号": {
54				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":false,"manifest_id":"APP-1"`) + `},"manifests":{` + manifest("APP-1", entryA1) + `}}`,
55				[]string{"A-1", "APP-1"},
56			},
57			"同一档案出现在两份清册": {
58				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":true,"manifest_id":"APP-1"`) + `},"manifests":{` + manifest("APP-1", entryA1) + `,` + manifest("APP-2", entryA1) + `}}`,
59				[]string{"A-1", "APP-2"},
60			},
61			"归属指向别的申请": {
62				`{"version":1,"archives":{"A-1":` + archive(`,"destroyed":true,"manifest_id":"APP-2"`) + `},"manifests":{` + manifest("APP-1", entryA1) + `,` + manifest("APP-2", "") + `}}`,
63				[]string{"A-1", "APP-2"},
64			},
65		}
66		for name, tc := range corrupt {
67			t.Run(name, func(t *testing.T) {
68				dir := t.TempDir()
69				writeStateFile(t, dir, tc.state)
70	
71				s, err := Open(dir)
72				if err == nil {
73					s.Close()
74					t.Fatal("销毁状态与清册对应不上时不应打开成功")
75				}
76				if !errors.Is(err, ErrCorruptState) {
77					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
78				}
79				for _, id := range tc.wantIDs {
80					if !strings.Contains(err.Error(), id) {
81						t.Fatalf("错误信息应指出 %s，得到 %v", id, err)
82					}
83				}
84				if got := readStateFile(t, dir); got != tc.state {
85					t.Fatalf("打开失败后原文件被改动:\n%q", got)
86				}
87			})
88		}
89	}
90	
91	// 保管库打开后保存内容才出现销毁状态与清册不对应：下一次使用有效输入的
92	// 查询、核对与办理都必须按记录损坏失败——即使操作的是另一份档案——
93	// 不返回正常历史、清册或部分报告，不留下任何变更，原保存内容保持原样。
94	func TestManifestCorruptionAfterOpenFailsAllOperations(t *testing.T) {
95		dir := t.TempDir()
96		s, err := Open(dir)
97		if err != nil {
98			t.Fatal(err)
99		}
100		defer s.Close()
101		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
102		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-01-10")
103		if _, err := s.Destroy(DestructionRequest{
104			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
105		}); err != nil {
106			t.Fatal(err)
107		}
108		if _, found, err := s.History("A-1"); err != nil || !found {
109			t.Fatalf("损坏前查询应成功: found=%v err=%v", found, err)
110		}
111	
112		// 清册 APP-1 仍在，但把 A-1 改回未销毁：清册收录了未销毁档案。
113		rewriteState(t, dir, func(doc map[string]any) {
114			doc["archives"].(map[string]any)["A-1"].(map[string]any)["destroyed"] = false
115		})
116		corruptContent := readStateFile(t, dir)
117	
118		// 重新打开必须失败，错误指出 A-1 与 APP-1。
119		s2, err := Open(dir)
120		if err == nil {
121			s2.Close()
122			t.Fatal("清册收录未销毁档案时，打开必须失败")
123		}
124		if !errors.Is(err, ErrCorruptState) ||
125			!strings.Contains(err.Error(), "A-1") || !strings.Contains(err.Error(), "APP-1") {
126			t.Fatalf("打开错误应为 ErrCorruptState 并指出 A-1/APP-1，得到 %v", err)
127		}
128	
129		// 已打开的实例：即使只操作无关的 A-2，也必须按整库损坏失败。
130		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
131			t.Fatalf("损坏后 History 必须返回 ErrCorruptState 且无结论: found=%v err=%v", found, err)
132		}
133		if _, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found {
134			t.Fatalf("损坏后 GetManifest 必须返回 ErrCorruptState: found=%v err=%v", found, err)
135		}
136		if r, err := s.Check(CheckRequest{
137			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-2"},
138		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
139			t.Fatalf("损坏后 Check 必须失败且不得给出部分报告: %+v err=%v", r, err)
140		}
141		if m, err := s.Destroy(DestructionRequest{
142			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-2"},
143		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
144			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
145		}
146		if err := s.Register(RegisterInput{ID: "A-3", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-01-10")}); !errors.Is(err, ErrCorruptState) {
147			t.Fatalf("损坏后 Register 必须失败: %v", err)
148		}
149	
150		// 失败不得触发修复：不补清册、不改销毁标记、不删冲突记录。
151		if got := readStateFile(t, dir); got != corruptContent {
152			t.Fatalf("失败后原保存内容被改动:\n%q", got)
153		}
154	}
155	
156	// 已销毁档案的清册在打开后被删掉：档案记下的申请编号找不到清册，
157	// 后续所有操作同样必须按记录损坏失败，不能返回没有清册的正常历史。
158	func TestManifestDeletedAfterOpenFailsAllOperations(t *testing.T) {
159		dir := t.TempDir()
160		s, err := Open(dir)
161		if err != nil {
162			t.Fatal(err)
163		}
