165		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
166		if _, err := s.Destroy(DestructionRequest{
167			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
168		}); err != nil {
169			t.Fatal(err)
170		}
171	
172		rewriteState(t, dir, func(doc map[string]any) {
173			delete(doc["manifests"].(map[string]any), "APP-1")
174		})
175		corruptContent := readStateFile(t, dir)
176	
177		// 已销毁档案不得被重新判为可以销毁，也不能用另一申请编号再生成清册。
178		if r, err := s.Check(CheckRequest{
179			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
180		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
181			t.Fatalf("清册缺失后 Check 必须失败: %+v err=%v", r, err)
182		}
183		if m, err := s.Destroy(DestructionRequest{
184			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
185		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
186			t.Fatalf("清册缺失后不得用另一申请编号再销毁: %+v err=%v", m, err)
187		}
188		// 历史查询不得返回“已销毁但没有清册”的正常结论。
189		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
190			t.Fatalf("清册缺失后 History 必须失败且无结论: found=%v err=%v", found, err)
191		}
192		if got := readStateFile(t, dir); got != corruptContent {
193			t.Fatalf("失败后原保存内容被改动:\n%q", got)
194		}
195	}
196	
197	// 对应关系完好的合法记录不受影响：未销毁且无清册归属的档案合法，
198	// 合法销毁后的历史与原清册完整可查，相同申请重放仍取回原清册；
199	// 引入期限修订前保存的销毁记录（没有 initial_end）也能正常打开。
200	func TestValidManifestLinksKeepWorking(t *testing.T) {
201		t.Run("销毁后的对应关系可查且可重放", func(t *testing.T) {
202			s := openTestStore(t)
203			reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
204			reg(t, s, "A-2", "凭证", "2020-01-01", "2025-01-10")
205			m1, err := s.Destroy(DestructionRequest{
206				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
207			})
208			if err != nil {
209				t.Fatal(err)
210			}
211			h, found, err := s.History("A-1")
212			if err != nil || !found || h.Manifest == nil || h.ManifestApplicationID != "APP-1" {
213				t.Fatalf("销毁后历史应带原清册: found=%v err=%v %+v", found, err, h)
214			}
215			m2, err := s.Destroy(DestructionRequest{
216				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
217			})
218			if err != nil || m2.ApplicationID != m1.ApplicationID || len(m2.Entries) != 1 {
219				t.Fatalf("相同申请重放应取回原清册: %+v err=%v", m2, err)
220			}
221			// 未销毁且没有清册归属的档案是合法记录。
222			h2, found, err := s.History("A-2")
223			if err != nil || !found || h2.Destroyed || h2.ManifestApplicationID != "" || h2.Manifest != nil {
224				t.Fatalf("未销毁档案不应有清册归属: %+v err=%v", h2, err)
225			}
226		})
227	
228		t.Run("旧格式销毁记录可打开", func(t *testing.T) {
229			dir := t.TempDir()
230			writeStateFile(t, dir, `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","destroyed":true,"manifest_id":"APP-1","freezes":[]}},"manifests":{"APP-1":{"application_id":"APP-1","processed_on":"2025-01-10","entries":[{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10"}]}}}`)
231			s, err := Open(dir)
232			if err != nil {
233				t.Fatalf("修订功能之前保存的销毁记录应能打开: %v", err)
234			}
235			defer s.Close()
236			h, found, err := s.History("A-1")
237			if err != nil || !found || h.Manifest == nil {
238				t.Fatalf("旧格式销毁记录的历史应完整可查: found=%v err=%v", found, err)
239			}
240		})
241	}
