28		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-01-07")}); err != nil {
29			t.Fatal(err)
30		}
31		if _, err := s.Destroy(DestructionRequest{
32			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-2"},
33		}); err != nil {
34			t.Fatal(err)
35		}
36		if err := s.Close(); err != nil {
37			t.Fatal(err)
38		}
39	
40		// 关闭后重新打开同一位置，已成功办理的记录必须完整可查。
41		s2, err := Open(dir)
42		if err != nil {
43			t.Fatalf("重新打开失败: %v", err)
44		}
45		h1, found, err := s2.History("A-1")
46		if err != nil || !found {
47			t.Fatalf("A-1 重开后丢失: %v %v", found, err)
48		}
49		if h1.Destroyed {
50			t.Fatal("A-1 不应处于销毁状态")
51		}
52		if len(h1.Freezes) != 2 || len(h1.ActiveFreezes) != 1 {
53			t.Fatalf("冻结/解除历史不完整: %+v", h1.Freezes)
54		}
55		f1 := h1.Freezes[0]
56		if !f1.Released || f1.ReleaseReason != "结案" || !f1.ReleasedOn.Equal(MustParseDate("2025-01-06")) {
57			t.Fatalf("解除信息重开后不正确: %+v", f1)
58		}
59		if h1.Freezes[1].Released || h1.ActiveFreezes[0].ID != "F-2" {
60			t.Fatalf("F-2 应仍未解除: %+v", h1.Freezes)
61		}
62	
63		h2, found, _ := s2.History("A-2")
64		if !found || !h2.Destroyed || h2.ManifestApplicationID != "APP-1" {
65			t.Fatalf("A-2 销毁状态重开后不正确: %+v found=%v", h2, found)
66		}
67		if h2.Manifest == nil || !h2.Manifest.ProcessedOn.Equal(MustParseDate("2025-01-10")) ||
68			len(h2.Manifest.Entries) != 1 || h2.Manifest.Entries[0].Category != "凭证" {
69			t.Fatalf("清册重开后不完整: %+v", h2.Manifest)
70		}
71		m, found, err := s2.GetManifest("APP-1")
72		if err != nil || !found || m.ApplicationID != "APP-1" {
73			t.Fatalf("按申请编号查不到清册: %v %v %+v", found, err, m)
74		}
75	
76		// 重开后业务仍可继续办理：解除 F-2 后销毁 A-1。
77		if err := s2.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计结束", ReleasedOn: MustParseDate("2025-01-10")}); err != nil {
