87	// 同进程内两个指向同一位置的 Store 并发办理，也要有明确先后。
88	func TestConcurrentStoresInProcess(t *testing.T) {
89		dir := t.TempDir()
90		setup, err := Open(dir)
91		if err != nil {
92			t.Fatal(err)
93		}
94		reg(t, setup, "A-1", "合同", "2020-01-01", "2025-01-10")
95		if err := setup.Close(); err != nil {
96			t.Fatal(err)
97		}
98	
99		for round := 0; round < 30; round++ {
100			s1, err := Open(dir)
101			if err != nil {
102				t.Fatal(err)
103			}
104			s2, err := Open(dir)
105			if err != nil {
106				t.Fatal(err)
107			}
108			freezeID := fmt.Sprintf("F-%d", round)
109	
110			var wg sync.WaitGroup
111			var freezeErr, destroyErr error
112			wg.Add(2)
113			go func() {
114				defer wg.Done()
115				freezeErr = s1.Freeze(FreezeInput{
116					ArchiveID: "A-1", FreezeID: freezeID, Reason: "诉讼",
117					FrozenOn: MustParseDate("2025-01-10"),
118				})
119			}()
120			go func() {
121				defer wg.Done()
122				_, destroyErr = s2.Destroy(DestructionRequest{
123					ApplicationID: fmt.Sprintf("APP-%d", round),
124					ProcessedOn:   MustParseDate("2025-01-10"),
125					ArchiveIDs:    []string{"A-1"},
126				})
127			}()
128			wg.Wait()
129	
130			switch {
131			case freezeErr == nil && destroyErr == nil:
132				t.Fatalf("第 %d 轮：冻结与销毁同时成功，违反互斥", round)
133			case freezeErr != nil && destroyErr != nil:
134				// 仅当销毁先成功时，冻结才应因已销毁失败；这一轮销毁不应失败。
135				t.Fatalf("第 %d 轮：两者都失败 freeze=%v destroy=%v", round, freezeErr, destroyErr)
136			case freezeErr == nil:
137				// 冻结先成功：销毁必须被未解除冻结挡住。
138				if !errors.Is(destroyErr, ErrActiveFreeze) {
139					t.Fatalf("第 %d 轮：冻结先成功却未挡住销毁: %v", round, destroyErr)
140				}
141				// 解除后下一轮可销毁；为保持后续轮次语义，这里直接解除。
142				if err := s1.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: freezeID, Reason: "结案", ReleasedOn: MustParseDate("2025-01-10")}); err != nil {
143					t.Fatal(err)
144				}
145			default:
146				// 销毁先成功：冻结必须因档案已销毁失败，后续轮次无需继续。
147				if !errors.Is(freezeErr, ErrDestroyed) {
148					t.Fatalf("第 %d 轮：销毁先成功，后续冻结应失败: %v", round, freezeErr)
149				}
150				h, found, _ := s1.History("A-1")
151				if !found || !h.Destroyed || len(h.ActiveFreezes) != 0 {
152					t.Fatalf("第 %d 轮：销毁成功后状态不正确: %+v", round, h)
153				}
154				s1.Close()
155				s2.Close()
156				return
157			}
158			s1.Close()
159			s2.Close()
160		}
161	}
162	
163	// --- 跨进程并发：两个独立的本机程序同时办理同一档案 ---
164	
165	// TestSubprocessHelper 不是普通测试，只在被父进程以辅助进程方式启动时执行单次操作。
166	func TestSubprocessHelper(t *testing.T) {
167		dir := os.Getenv("RETENTION_HELPER_DIR")
168		if dir == "" {
169			return
170		}
171		op := os.Getenv("RETENTION_HELPER_OP")
172		s, err := Open(dir)
173		if err != nil {
174			fmt.Fprintf(os.Stderr, "open: %v\n", err)
175			os.Exit(2)
176		}
177		switch op {
178		case "freeze":
179			err = s.Freeze(FreezeInput{
180				ArchiveID: "A-1", FreezeID: os.Getenv("RETENTION_HELPER_FREEZE_ID"),
181				Reason: "诉讼", FrozenOn: MustParseDate("2025-01-10"),
182			})
183		case "destroy":
184			_, err = s.Destroy(DestructionRequest{
185				ApplicationID: "APP-X", ProcessedOn: MustParseDate("2025-01-10"),
186				ArchiveIDs: []string{"A-1"},
187			})
188		default:
189			fmt.Fprintf(os.Stderr, "unknown op %q\n", op)
190			os.Exit(2)
191		}
192		if err != nil {
193			// 业务失败以退出码 3 回传，最后一行给出错误哨兵，供父进程分类。
194			fmt.Printf("ERROR: %v\n", err)
195			os.Exit(3)
196		}
197	}
198	
199	type helperResult struct {
200		op      string
201		failed  bool
202		message string
203	}
204	
205	func runHelper(t *testing.T, dir, op, freezeID string) helperResult {
206		t.Helper()
207		cmd := exec.Command(os.Args[0], "-test.run=TestSubprocessHelper", "-test.v")
208		cmd.Env = append(os.Environ(),
209			"RETENTION_HELPER_DIR="+dir,
210			"RETENTION_HELPER_OP="+op,
211			"RETENTION_HELPER_FREEZE_ID="+freezeID,
212		)
213		out, _ := cmd.CombinedOutput()
214		r := helperResult{op: op, failed: !cmd.ProcessState.Success()}
215		last := ""
216		for _, line := range splitLines(string(out)) {
217			if line == "PASS" || line == "FAIL" || line == "SKIP" {
218				continue
219			}
220			last = line
221		}
222		r.message = last
223		return r
224	}
225	
226	func splitLines(s string) []string {
227		var lines []string
228		start := 0
229		for i := 0; i < len(s); i++ {
230			if s[i] == '\n' {
231				lines = append(lines, s[start:i])
232				start = i + 1
233			}
234		}
235		if start < len(s) {
236			lines = append(lines, s[start:])
237		}
238		return lines
239	}
240	
241	func TestCrossProcessFreezeVsDestroy(t *testing.T) {
242		for round := 0; round < 10; round++ {
243			dir := filepath.Join(t.TempDir(), "vault")
244			setup, err := Open(dir)
245			if err != nil {
246				t.Fatal(err)
247			}
248			reg(t, setup, "A-1", "合同", "2020-01-01", "2025-01-10")
249			if err := setup.Close(); err != nil {
250				t.Fatal(err)
251			}
252	
253			freezeID := fmt.Sprintf("F-%d", round)
254			var wg sync.WaitGroup
255			results := make([]helperResult, 2)
256			wg.Add(2)
257			go func() { defer wg.Done(); results[0] = runHelper(t, dir, "freeze", freezeID) }()
258			go func() { defer wg.Done(); results[1] = runHelper(t, dir, "destroy", freezeID) }()
259			wg.Wait()
260	
261			var freezeRes, destroyRes helperResult
262			for _, r := range results {
263				if r.op == "freeze" {
264					freezeRes = r
265				} else {
266					destroyRes = r
267				}
268			}
269	
270			check, err := Open(dir)
271			if err != nil {
272				t.Fatal(err)
273			}
274			h, found, _ := check.History("A-1")
275			if !found {
276				t.Fatalf("第 %d 轮：档案丢失", round)
277			}
278			// 核心不变量：绝不能既已销毁又存在未解除冻结。
279			if h.Destroyed && len(h.ActiveFreezes) != 0 {
280				t.Fatalf("第 %d 轮：出现已销毁但仍有未解除冻结的记录: %+v", round, h)
281			}
282	
283			switch {
284			case !freezeRes.failed && !destroyRes.failed:
285				t.Fatalf("第 %d 轮：两个程序同时成功", round)
286			case !freezeRes.failed:
287				t.Logf("第 %d 轮：冻结先成功", round)
288				// 冻结先成功，销毁必须明确失败。
289				if !destroyRes.failed || !contains(destroyRes.message, "冻结") {
290					t.Fatalf("第 %d 轮：冻结先成功却未挡住销毁: %+v", round, destroyRes)
291				}
292				if h.Destroyed || len(h.ActiveFreezes) != 1 {
293					t.Fatalf("第 %d 轮：冻结成功后状态错误: %+v", round, h)
294				}
295			default:
296				t.Logf("第 %d 轮：销毁先成功", round)
297				// 销毁先成功，后续冻结必须明确失败。
298				if freezeRes.failed != true || !contains(freezeRes.message, "销毁") {
299					t.Fatalf("第 %d 轮：销毁先成功却未阻止冻结: %+v", round, freezeRes)
300				}
301				if !h.Destroyed {
302					t.Fatalf("第 %d 轮：销毁结果未持久化", round)
303				}
304			}
305			check.Close()
306		}
307	}
308	
309	func contains(s, sub string) bool {
310		for i := 0; i+len(sub) <= len(s); i++ {
311			if s[i:i+len(sub)] == sub {
312				return true
313			}
314		}
315		return false
316	}
